query ForSaleNonPriorityQuery($zpid: ID!, $altId: ID, $skipPropertyAddress: Boolean = false, $skipPropertyPrice: Boolean = false) {
  property(zpid: $zpid, palsId: $altId) {
    zpid
    ...ActionBarMenu_property
    ...NonPriorityModules_property
    ...FsLightboxes_property
    ...FsRichMedia_property
    ...IMXLightboxEntryFragments_property
    ...ZMV_PROPERTY_FRAGMENT
  }
  zgProperty(propertyId: $zpid) {
    ...NonPriorityModules_ZGProperty
  }
  viewer {
    ...ActionBarMenu_viewer
    ...FsLightboxes_viewer
    ...NonPriorityModules_viewer
  }
  richMedia(zpid: $zpid, palsId: $altId) {
    carouselPhotos(aspectRatio: Original) {
      highRes {
        id
      }
      mls {
        id
      }
    }
    ...ZMV_RICH_MEDIA_FRAGMENT
  }
}

